/*
 * Reimplementation of the samtools command-line dispatcher.
 *
 * Only a small subset of samtools subcommands is implemented here:
 * the main program banner/usage, the version details, the `flags`
 * subcommand, and a dispatcher for `help` and unrecognized commands.
 * All other samtools subcommands (view, sort, index, ...) are not
 * implemented; invoking them prints an "unrecognized command" error
 * just like invoking a completely unknown command would.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <stdint.h>
#include <errno.h>

static const char SAMTOOLS_VERSION[] = "be7a51c";
static const char HTSLIB_VERSION[]   = "1.23.1";

static void print_main_usage(FILE *out)
{
    fprintf(out, "\n");
    fprintf(out, "Program: samtools (Tools for alignments in the SAM format)\n");
    fprintf(out, "Version: %s (using htslib %s)\n", SAMTOOLS_VERSION, HTSLIB_VERSION);
    fprintf(out, "\n");
    fprintf(out, "Usage:   samtools <command> [options]\n");
    fprintf(out, "\n");
    fprintf(out, "Commands:\n");
    fprintf(out, "  -- Indexing\n");
    fprintf(out, "     dict           create a sequence dictionary file\n");
    fprintf(out, "     faidx          index/extract FASTA\n");
    fprintf(out, "     fqidx          index/extract FASTQ\n");
    fprintf(out, "     index          index alignment\n");
    fprintf(out, "\n");
    fprintf(out, "  -- Editing\n");
    fprintf(out, "     calmd          recalculate MD/NM tags and '=' bases\n");
    fprintf(out, "     fixmate        fix mate information\n");
    fprintf(out, "     reheader       replace BAM header\n");
    fprintf(out, "     targetcut      cut fosmid regions (for fosmid pool only)\n");
    fprintf(out, "     addreplacerg   adds or replaces RG tags\n");
    fprintf(out, "     markdup        mark duplicates\n");
    fprintf(out, "     ampliconclip   clip oligos from the end of reads\n");
    fprintf(out, "\n");
    fprintf(out, "  -- File operations\n");
    fprintf(out, "     collate        shuffle and group alignments by name\n");
    fprintf(out, "     cat            concatenate BAMs\n");
    fprintf(out, "     consensus      produce a consensus Pileup/FASTA/FASTQ\n");
    fprintf(out, "     merge          merge sorted alignments\n");
    fprintf(out, "     mpileup        multi-way pileup\n");
    fprintf(out, "     sort           sort alignment file\n");
    fprintf(out, "     split          splits a file by read group\n");
    fprintf(out, "     quickcheck     quickly check if SAM/BAM/CRAM file appears intact\n");
    fprintf(out, "     fastq          converts a BAM to a FASTQ\n");
    fprintf(out, "     fasta          converts a BAM to a FASTA\n");
    fprintf(out, "     import         Converts FASTA or FASTQ files to SAM/BAM/CRAM\n");
    fprintf(out, "     reference      Generates a reference from aligned data\n");
    fprintf(out, "     reset          Reverts aligner changes in reads\n");
    fprintf(out, "\n");
    fprintf(out, "  -- Statistics\n");
    fprintf(out, "     bedcov         read depth per BED region\n");
    fprintf(out, "     coverage       alignment depth and percent coverage\n");
    fprintf(out, "     depth          compute the depth\n");
    fprintf(out, "     flagstat       simple stats\n");
    fprintf(out, "     idxstats       BAM index stats\n");
    fprintf(out, "     cram-size      list CRAM Content-ID and Data-Series sizes\n");
    fprintf(out, "     phase          phase heterozygotes\n");
    fprintf(out, "     stats          generate stats (former bamcheck)\n");
    fprintf(out, "     ampliconstats  generate amplicon specific stats\n");
    fprintf(out, "     checksum       produce order-agnostic checksums of sequence content\n");
    fprintf(out, "\n");
    fprintf(out, "  -- Viewing\n");
    fprintf(out, "     flags          explain BAM flags\n");
    fprintf(out, "     head           header viewer\n");
    fprintf(out, "     tview          text alignment viewer\n");
    fprintf(out, "     view           SAM<->BAM<->CRAM conversion\n");
    fprintf(out, "     depad          convert padded BAM to unpadded BAM\n");
    fprintf(out, "     samples        list the samples in a set of SAM/BAM/CRAM files\n");
    fprintf(out, "\n");
    fprintf(out, "  -- Misc\n");
    fprintf(out, "     help [cmd]     display this help message or help for [cmd]\n");
    fprintf(out, "     version        detailed version information\n");
    fprintf(out, "\n");
}

static void print_version(FILE *out)
{
    fprintf(out, "samtools %s\n", SAMTOOLS_VERSION);
    fprintf(out, "Using htslib %s\n", HTSLIB_VERSION);
    fprintf(out, "Copyright (C) 2025 Genome Research Ltd.\n");
    fprintf(out, "\n");
    fprintf(out, "Samtools compilation details:\n");
    fprintf(out, "    Features:       build=configure curses=yes \n");
    fprintf(out, "    CC:             gcc\n");
    fprintf(out, "    CPPFLAGS:       \n");
    fprintf(out, "    CFLAGS:         -Wall -g -O2\n");
    fprintf(out, "    LDFLAGS:        \n");
    fprintf(out, "    HTSDIR:         htslib\n");
    fprintf(out, "    LIBS:           \n");
    fprintf(out, "    CURSES_LIB:     -lncursesw\n");
    fprintf(out, "\n");
    fprintf(out, "HTSlib compilation details:\n");
    fprintf(out, "    Features:       build=Makefile libcurl=yes S3=no GCS=no libdeflate=no lzma=yes bzip2=yes plugins=no htscodecs=1.6.6\n");
    fprintf(out, "    CC:             gcc\n");
    fprintf(out, "    CPPFLAGS:       \n");
    fprintf(out, "    CFLAGS:         -g -Wall -O2 -fvisibility=hidden\n");
    fprintf(out, "    LDFLAGS:        -fvisibility=hidden\n");
    fprintf(out, "\n");
    fprintf(out, "HTSlib URL scheme handlers present:\n");
    fprintf(out, "    built-in:\t file, preload, data\n");
    fprintf(out, "    libcurl:\t gophers, smtp, ldaps, smb, rtsp, tftp, pop3, smbs, imaps, pop3s, ftps, https, http, ftp, gopher, imap, sftp, ldap, smtps, scp, dict, mqtt, telnet, rtmp\n");
    fprintf(out, "    crypt4gh-needed:\t crypt4gh\n");
    fprintf(out, "    mem:\t mem\n");
}

/* --- samtools flags subcommand --- */

struct flag_def {
    unsigned int value;
    const char *name;
    const char *desc;
};

static const struct flag_def FLAG_DEFS[] = {
    { 0x001, "PAIRED",        "paired-end / multiple-segment sequencing technology" },
    { 0x002, "PROPER_PAIR",   "each segment properly aligned according to aligner" },
    { 0x004, "UNMAP",         "segment unmapped" },
    { 0x008, "MUNMAP",        "next segment in the template unmapped" },
    { 0x010, "REVERSE",       "SEQ is reverse complemented" },
    { 0x020, "MREVERSE",      "SEQ of next segment in template is rev.complemented" },
    { 0x040, "READ1",         "the first segment in the template" },
    { 0x080, "READ2",         "the last segment in the template" },
    { 0x100, "SECONDARY",     "secondary alignment" },
    { 0x200, "QCFAIL",        "not passing quality controls or other filters" },
    { 0x400, "DUP",           "PCR or optical duplicate" },
    { 0x800, "SUPPLEMENTARY", "supplementary alignment" },
};
static const size_t FLAG_DEFS_COUNT = sizeof(FLAG_DEFS) / sizeof(FLAG_DEFS[0]);

static void flags_print_usage(FILE *out)
{
    fprintf(out,
        "About: Convert between textual and numeric flag representation\n"
        "Usage: samtools flags FLAGS...\n"
        "\n"
        "Each FLAGS argument is either an INT (in decimal/hexadecimal/octal) representing\n"
        "a combination of the following numeric flag values, or a comma-separated string\n"
        "NAME,...,NAME representing a combination of the following flag names:\n"
        "\n"
        "   0x1     1  PAIRED         paired-end / multiple-segment sequencing technology\n"
        "   0x2     2  PROPER_PAIR    each segment properly aligned according to aligner\n"
        "   0x4     4  UNMAP          segment unmapped\n"
        "   0x8     8  MUNMAP         next segment in the template unmapped\n"
        "  0x10    16  REVERSE        SEQ is reverse complemented\n"
        "  0x20    32  MREVERSE       SEQ of next segment in template is rev.complemented\n"
        "  0x40    64  READ1          the first segment in the template\n"
        "  0x80   128  READ2          the last segment in the template\n"
        " 0x100   256  SECONDARY      secondary alignment\n"
        " 0x200   512  QCFAIL         not passing quality controls or other filters\n"
        " 0x400  1024  DUP            PCR or optical duplicate\n"
        " 0x800  2048  SUPPLEMENTARY  supplementary alignment\n");
}

/* Case-insensitive string compare. */
static int strcaseequal(const char *a, const char *b)
{
    while (*a && *b) {
        if (tolower((unsigned char)*a) != tolower((unsigned char)*b))
            return 0;
        a++; b++;
    }
    return *a == '\0' && *b == '\0';
}

static int lookup_flag_name(const char *name, unsigned int *out_val)
{
    for (size_t i = 0; i < FLAG_DEFS_COUNT; i++) {
        if (strcaseequal(name, FLAG_DEFS[i].name)) {
            *out_val = FLAG_DEFS[i].value;
            return 1;
        }
    }
    return 0;
}

/*
 * Parse a single FLAGS argument.  Returns 1 on success (and stores the
 * parsed numeric value in *out_val), or 0 on failure.
 *
 * Behaviour matches the observed reference:
 *   - If the argument begins with a digit or '+' / '-' sign, it is parsed
 *     as an integer using strtoul on the unsigned form.  Leading "0x"
 *     means hex, leading "0" means octal.  Any trailing characters are
 *     simply ignored (e.g. "2048,UNMAP" is treated as 2048).
 *   - Otherwise it is split on commas and each token looked up as a
 *     case-insensitive flag name.  Empty tokens cause failure.
 */
static int parse_flags_arg(const char *s, unsigned int *out_val)
{
    if (s == NULL || *s == '\0')
        return 0;
    if (isdigit((unsigned char)s[0])) {
        char *endp = NULL;
        errno = 0;
        unsigned long v = strtoul(s, &endp, 0);
        if (endp == s)
            return 0;
        *out_val = (unsigned int)v;
        return 1;
    }
    /* parse as comma-separated names */
    unsigned int total = 0;
    const char *p = s;
    while (*p) {
        const char *start = p;
        while (*p && *p != ',') p++;
        size_t len = (size_t)(p - start);
        if (len == 0)
            return 0;
        char buf[64];
        if (len >= sizeof(buf))
            return 0;
        memcpy(buf, start, len);
        buf[len] = '\0';
        unsigned int v = 0;
        if (!lookup_flag_name(buf, &v))
            return 0;
        total |= v;
        if (*p == ',') p++;
        else break;
    }
    /* must have consumed entire string */
    if (*p != '\0')
        return 0;
    *out_val = total;
    return 1;
}

static void print_flag_combo(FILE *out, unsigned int val)
{
    fprintf(out, "0x%x\t%u\t", val, val);
    int first = 1;
    for (size_t i = 0; i < FLAG_DEFS_COUNT; i++) {
        if (val & FLAG_DEFS[i].value) {
            if (!first) fputc(',', out);
            fputs(FLAG_DEFS[i].name, out);
            first = 0;
        }
    }
    fputc('\n', out);
}

static int cmd_flags(int argc, char **argv)
{
    if (argc < 2) {
        flags_print_usage(stdout);
        return 0;
    }
    for (int i = 1; i < argc; i++) {
        unsigned int v = 0;
        if (!parse_flags_arg(argv[i], &v)) {
            fprintf(stderr, "samtools flags: Could not parse \"%s\"\n", argv[i]);
            flags_print_usage(stderr);
            return 1;
        }
        print_flag_combo(stdout, v);
    }
    return 0;
}

/* --- dispatcher --- */

static int dispatch(int argc, char **argv);

static int cmd_help(int argc, char **argv)
{
    if (argc < 2) {
        print_main_usage(stdout);
        return 0;
    }
    /* Run the command with no extra arguments so that it prints its own
     * usage text.  This mirrors the observed reference behaviour: for
     * example `samtools help flags` produces the same output as
     * `samtools flags` with no arguments. */
    char *subargv[2];
    subargv[0] = argv[1];
    subargv[1] = NULL;
    return dispatch(1, subargv);
}

static int cmd_version(int argc, char **argv)
{
    (void)argc; (void)argv;
    print_version(stdout);
    return 0;
}

static int dispatch(int argc, char **argv)
{
    if (argc < 1 || argv[0] == NULL) {
        print_main_usage(stderr);
        return 1;
    }
    const char *cmd = argv[0];
    if (strcmp(cmd, "flags") == 0) return cmd_flags(argc, argv);
    if (strcmp(cmd, "version") == 0) return cmd_version(argc, argv);
    if (strcmp(cmd, "help") == 0) return cmd_help(argc, argv);
    fprintf(stderr, "[main] unrecognized command '%s'\n", cmd);
    return 1;
}

int main(int argc, char **argv)
{
    if (argc < 2) {
        print_main_usage(stderr);
        return 1;
    }
    /* Accept --help and --version as aliases at the top level, but not
     * -h / -v which the reference treats as unknown commands. */
    if (strcmp(argv[1], "--help") == 0) {
        print_main_usage(stdout);
        return 0;
    }
    if (strcmp(argv[1], "--version") == 0) {
        print_version(stdout);
        return 0;
    }
    return dispatch(argc - 1, argv + 1);
}
EOF
echo "done"

