    { 0x800, "SUPPLEMENTARY", "supplementary alignment" },
};
static const size_t FLAG_DEFS_COUNT = sizeof(FLAG_DEFS) / sizeof(FLAG_DEFS[0]);

static void flags_print_usage(FILE *out)
{
    fprintf(out,
        "About: Convert between textual and numeric flag representation\n"
        "Usage: samtools flags FLAGS...\n"
        "\n"
        "Each FLAGS argument is either an INT (in decimal/hexadecimal/octal) representing\n"
        "a combination of the following numeric flag values, or a comma-separated string\n"
        "NAME,...,NAME representing a combination of the following flag names:\n"
        "\n"
        "   0x1     1  PAIRED         paired-end / multiple-segment sequencing technology\n"
        "   0x2     2  PROPER_PAIR    each segment properly aligned according to aligner\n"
        "   0x4     4  UNMAP          segment unmapped\n"
        "   0x8     8  MUNMAP         next segment in the template unmapped\n"
        "  0x10    16  REVERSE        SEQ is reverse complemented\n"
        "  0x20    32  MREVERSE       SEQ of next segment in template is rev.complemented\n"
        "  0x40    64  READ1          the first segment in the template\n"
        "  0x80   128  READ2          the last segment in the template\n"
        " 0x100   256  SECONDARY      secondary alignment\n"
        " 0x200   512  QCFAIL         not passing quality controls or other filters\n"
        " 0x400  1024  DUP            PCR or optical duplicate\n"
        " 0x800  2048  SUPPLEMENTARY  supplementary alignment\n");
}

/* Case-insensitive string compare. */
static int strcaseequal(const char *a, const char *b)
{
    while (*a && *b) {
        if (tolower((unsigned char)*a) != tolower((unsigned char)*b))
            return 0;
        a++; b++;
    }
    return *a == '\0' && *b == '\0';
}

static int lookup_flag_name(const char *name, unsigned int *out_val)
{
    for (size_t i = 0; i < FLAG_DEFS_COUNT; i++) {
        if (strcaseequal(name, FLAG_DEFS[i].name)) {
            *out_val = FLAG_DEFS[i].value;
            return 1;
        }
    }
    return 0;
}

/*
 * Parse a single FLAGS argument.  Returns 1 on success (and stores the
 * parsed numeric value in *out_val), or 0 on failure.
 *
 * Behaviour matches the observed reference:
 *   - If the argument begins with a digit or '+' / '-' sign, it is parsed
 *     as an integer using strtoul on the unsigned form.  Leading "0x"
 *     means hex, leading "0" means octal.  Any trailing characters are
 *     simply ignored (e.g. "2048,UNMAP" is treated as 2048).
 *   - Otherwise it is split on commas and each token looked up as a
 *     case-insensitive flag name.  Empty tokens cause failure.
 */
static int parse_flags_arg(const char *s, unsigned int *out_val)
{
    if (s == NULL || *s == '\0')
        return 0;
    if (isdigit((unsigned char)s[0])) {
        char *endp = NULL;
        errno = 0;
        unsigned long v = strtoul(s, &endp, 0);
        if (endp == s)
            return 0;
        *out_val = (unsigned int)v;
        return 1;
    }
    /* parse as comma-separated names */
    unsigned int total = 0;
    const char *p = s;
    while (*p) {
        const char *start = p;
        while (*p && *p != ',') p++;
        size_t len = (size_t)(p - start);
        if (len == 0)
            return 0;
        char buf[64];
        if (len >= sizeof(buf))
            return 0;
        memcpy(buf, start, len);
        buf[len] = '\0';
        unsigned int v = 0;
        if (!lookup_flag_name(buf, &v))
            return 0;
        total |= v;
        if (*p == ',') p++;
        else break;
    }
    /* must have consumed entire string */
    if (*p != '\0')
        return 0;
    *out_val = total;
    return 1;
}

static void print_flag_combo(FILE *out, unsigned int val)
{
    fprintf(out, "0x%x\t%u\t", val, val);
    int first = 1;
    for (size_t i = 0; i < FLAG_DEFS_COUNT; i++) {
        if (val & FLAG_DEFS[i].value) {
            if (!first) fputc(',', out);
            fputs(FLAG_DEFS[i].name, out);
            first = 0;
        }
    }
    fputc('\n', out);
}

static int cmd_flags(int argc, char **argv)
{
    if (argc < 2) {
        flags_print_usage(stdout);
        return 0;
    }
    for (int i = 1; i < argc; i++) {
        unsigned int v = 0;
        if (!parse_flags_arg(argv[i], &v)) {
            fprintf(stderr, "samtools flags: Could not parse \"%s\"\n", argv[i]);
            flags_print_usage(stderr);
            return 1;
        }
        print_flag_combo(stdout, v);
    }
    return 0;
}

/* --- dispatcher --- */

static int dispatch(int argc, char **argv);

static int cmd_help(int argc, char **argv)
{
    if (argc < 2) {
        print_main_usage(stdout);
        return 0;
    }
    /* Run the command with no extra arguments so that it prints its own
     * usage text.  This mirrors the observed reference behaviour: for
     * example `samtools help flags` produces the same output as
     * `samtools flags` with no arguments. */
    char *subargv[2];
    subargv[0] = argv[1];
    subargv[1] = NULL;
    return dispatch(1, subargv);
}

static int cmd_version(int argc, char **argv)
{
    (void)argc; (void)argv;
    print_version(stdout);
    return 0;
}

static int dispatch(int argc, char **argv)
{
    if (argc < 1 || argv[0] == NULL) {
        print_main_usage(stderr);
        return 1;
    }
    const char *cmd = argv[0];
    if (strcmp(cmd, "flags") == 0) return cmd_flags(argc, argv);
    if (strcmp(cmd, "version") == 0) return cmd_version(argc, argv);
    if (strcmp(cmd, "help") == 0) return cmd_help(argc, argv);
    fprintf(stderr, "[main] unrecognized command '%s'\n", cmd);
    return 1;
}

int main(int argc, char **argv)
{
    if (argc < 2) {
        print_main_usage(stderr);
        return 1;
    }
    /* Accept --help and --version as aliases at the top level, but not
     * -h / -v which the reference treats as unknown commands. */
    if (strcmp(argv[1], "--help") == 0) {
        print_main_usage(stdout);
        return 0;
    }
    if (strcmp(argv[1], "--version") == 0) {
        print_version(stdout);
        return 0;
    }
    return dispatch(argc - 1, argv + 1);
}
